    if ('endpoint' in file.network) network.endpoint = file.network.endpoint;
    if ('retries' in file.network) network.retries = file.network.retries;
    layer.network = network;
  }
  if ('ui' in file) {
    if (!isPlainObject(file.ui)) throw new TypeError('file.ui must be an object');
    const ui = {};
    if ('theme' in file.ui) ui.theme = file.ui.theme;
    if ('compact' in file.ui) ui.compact = file.ui.compact;
    layer.ui = ui;
  }
  if ('enabled' in file) layer.enabled = file.enabled;
  return layer;
}

function mergeGroup(...layers) {
  const result = {};
  for (const layer of layers) {
    if (!isPlainObject(layer)) continue;
    for (const key of Object.keys(layer)) {
